use serde :: { Deserialize , Serialize } ; use pretty_assertions :: assert_eq ; use super :: * ; impl CompactionResult { # [doc = " Create a new CompactionResult with the specified metrics"] pub fn new (original_tokens : usize , compacted_tokens : usize , original_messages : usize , compacted_messages : usize ,) -> Self { Self { original_tokens , compacted_tokens , original_messages , compacted_messages , } } # [doc = " Calculate the percentage reduction in tokens"] pub fn token_reduction_percentage (& self) -> f64 { if self . original_tokens == 0 || self . compacted_tokens == 0 { return 0.0 ; } ((self . original_tokens . saturating_sub (self . compacted_tokens)) as f64 / self . original_tokens as f64) * 100.0 } # [doc = " Calculate the percentage reduction in messages"] pub fn message_reduction_percentage (& self) -> f64 { if self . original_messages == 0 || self . compacted_messages == 0 { return 0.0 ; } ((self . original_messages . saturating_sub (self . compacted_messages)) as f64 / self . original_messages as f64) * 100.0 } }